import axios from 'axios';

const API_URL = "http://localhost:8085/v1/api/RapidAPI";

// Obtener todas las películas de Netflix
export const getAllNetflix = () => axios.get(`${API_URL}/Netflix/GetAll`);

// Cambiar estado de una película en Mongo
export const changeNetflixStatus = (id, status) => 
    axios.patch(`${API_URL}/Netflix/Mongo/changeStatus/${id}?status=${status}`);

// Buscar películas de Netflix en la API externa
export const searchNetflixFromAPI = (name) => 
    axios.get(`${API_URL}/Netflix/API/searchFull/${name}`);

// Crear una película en Mongo
export const createNetflix = (name, description) => {
    return axios.post(`${API_URL}/Netflix/save`, { name, description });
};

// Actualizar película en Mongo
export const updateNetflix = (oldName, name, description) => 
    axios.put(`${API_URL}/Netflix/Mongo/update`, { oldName, name, description });
